export const SPEECH_BY_ID: Record<string, SpeechAsset> = Object.fromEntries(SPEECH_ASSETS.map((a) => [a.assetId, a]));

export function speechByAssetId(id: string): SpeechAsset | undefined {
  return SPEECH_BY_ID[id];
}

// Pencarian: lewat chapterId + penutur + nomor urutan (1-based) di dalam chapter.
export function speechByChapter(chapterId: string, characterId: string, ordinal: number): SpeechAsset | undefined {
  const rel = SPEECH_ASSETS.filter((a) => a.chapterId === chapterId && a.characterId === characterId);
  return rel[Math.min(ordinal, rel.length) - 1] ?? rel[0];
}
